CREATE TABLE ONETIMEDESIGNCOMPONENTS (DESIGNCOMPONENTID NUMBER(19),PLANNEDDESIGNCOMPONENTID NUMBER(19), SUBNETWORKBOUNDARYID NUMBER(19), SYSTEMISSHARED NUMBER(19), SHARINGTYPEID NUMBER(5), MAJORHARDWAREOEMID NUMBER(5),MAJORSOFTWAREOEMID NUMBER(5),
PLATFORMID NUMBER(5),  MAJORSOFTWAREAPPLICATIONTYPE NVARCHAR2(2000), DESCRIPTION NVARCHAR2(2000), SYSTEMTYPEIDENTITYNAME NVARCHAR2(2000),PRODUCTNAMEID NUMBER(20), VODAFONENAMESID NUMBER, SYSTEMTYPEID  NUMBER(19),PLANNEDSYSTEMTYPEID NUMBER(19) , GDPRRELEVANT NUMBER(1),DESIGNCOMPONENTFAMILYID NUMBER(19),PlannedDESIGNCOMPONENTFAMILYID NUMBER(19), MAJORSOFTWAREBUILDSID NUMBER, MAJORHARDWAREBUILDSID NUMBER, VISIBLEFLAG NUMBER(1));

INSERT INTO ONETIMEDESIGNCOMPONENTS (DESIGNCOMPONENTID, SUBNETWORKBOUNDARYID,SYSTEMISSHARED,SHARINGTYPEID,MAJORHARDWAREOEMID,MAJORSOFTWAREOEMID,PLATFORMID,MAJORSOFTWAREAPPLICATIONTYPE,DESCRIPTION,SYSTEMTYPEIDENTITYNAME,PRODUCTNAMEID,
VODAFONENAMESID,SYSTEMTYPEID,GDPRRELEVANT,DESIGNCOMPONENTFAMILYID,MAJORSOFTWAREBUILDSID,VISIBLEFLAG)
SELECT distinct dc.DESIGNCOMPONENTID, dcf.SUBNETWORKBOUNDARYID, dcf.SYSTEMISSHARED,dcf.SHARINGTYPEID,dcf.MAJORHARDWAREOEMID, dcf.MAJORSOFTWAREOEMID,dcf.PLATFORMID,dcf.MAJORSOFTWAREAPPLICATIONTYPE,dcf.DESCRIPTION,
OriginalEquipmentManufacturer || ' ' || p.description || ' <b class=\"text-lowercase\"> on</b> Ericsson CEE-CNIS' as SYSTEMTYPEIDENTITYNAME ,dcf.PRODUCTNAMEID,dcf.VODAFONENAMESID,dc.SYSTEMTYPEID,dc.GDPRRELEVANT,dcf.DESIGNCOMPONENTFAMILYID,msb.MAJORSOFTWAREBUILDSID,dc.VISIBLEFLAG
FROM LCMENGINEERING lcm
join designcomponents dc on lcm.designcomponentid = dc.designcomponentid
join designcomponentfamilies dcf on dc.designcomponentfamilyid = dcf.designcomponentfamilyid
join productname p on dcf.productnameid = p.productnameid
join systemtypes st on dc.systemtypeid = st.systemtypeid
join Systemtypesmajorhardwarebuilds mh on mh.systemtypeid = st.systemtypeid AND ISMAIN = 1
join majorsoftwarebuilds msb on msb.majorsoftwarebuildsid = st.majorsoftwarebuildsid
join MajorHardwareBuilds mb on mh.majorhardwareid = mb.majorhardwareid
join platforms pf on mb.platformId = pf.platformId
join buildconstructions b on b.buildconstructionid = mb.buildconstructionid
join OriginalEquipmentManufacturers oem on oem.orgeqpmanufacturerid = msb.orgeqpmanufacturerid
join subnetworkboundaries snb on snb.id = dcf.subnetworkboundaryid
WHERE lcm.deleted = 0 and archived =0 AND pf.platform = 'VMWare NFVI' AND p.ISPLATFORMSOFTWARE = 0
AND p.DESCRIPTION in (Select Distinct Vendor_NF from ExodusPlanBackup where TargetInfra = 'CEE CNIS');
commit;


UPDATE ONETIMEDESIGNCOMPONENTS SET MAJORHARDWAREOEMID = (Select ORGEQPMANUFACTURERID from  ORIGINALEQUIPMENTMANUFACTURERS WHERE ORIGINALEQUIPMENTMANUFACTURER = 'Ericsson');
UPDATE ONETIMEDESIGNCOMPONENTS SET PLATFORMID = (Select PlatformId from  Platforms WHERE Platform = 'CEE-CNIS');
commit;
UPDATE ONETIMEDESIGNCOMPONENTS SET MAJORHARDWAREBUILDSID = (Select MAJORHARDWAREID from majorhardwarebuilds WHERE ORGEQPMANUFACTURERID = (Select ORGEQPMANUFACTURERID from  ORIGINALEQUIPMENTMANUFACTURERS WHERE ORIGINALEQUIPMENTMANUFACTURER = 'Ericsson') AND PLATFORMID = (Select PlatformId from  Platforms WHERE Platform = 'CEE-CNIS'));
commit;

INSERT INTO designcomponentfamilies (CREATIONUSER,MODIFICATIONUSER,DELETED,SUBNETWORKBOUNDARYID,SYSTEMISSHARED,SHARINGTYPEID,MAJORHARDWAREOEMID,MAJORSOFTWAREOEMID,PLATFORMID,MAJORSOFTWAREAPPLICATIONTYPE,DESCRIPTION,SYSTEMTYPEIDENTITYNAME,IMPLEMENTATION,PRODUCTNAMEID,VODAFONENAMESID)
Select distinct 1,1,0,SUBNETWORKBOUNDARYID,SYSTEMISSHARED,SHARINGTYPEID,MAJORHARDWAREOEMID,MAJORSOFTWAREOEMID,PLATFORMID,MAJORSOFTWAREAPPLICATIONTYPE,DESCRIPTION,SYSTEMTYPEIDENTITYNAME,0,PRODUCTNAMEID,VODAFONENAMESID from ONETIMEDESIGNCOMPONENTS;
--198 rows
commit;

UPDATE ONETIMEDESIGNCOMPONENTS odc SET PlannedDESIGNCOMPONENTFAMILYID = (SELECT Distinct dcf.DESIGNCOMPONENTFAMILYID
    FROM DesignComponentfamilies dcf
    WHERE odc.SYSTEMTYPEIDENTITYNAME = dcf.SYSTEMTYPEIDENTITYNAME
    AND odc.SUBNETWORKBOUNDARYID = dcf.SUBNETWORKBOUNDARYID
    AND dcf.deleted = 0
);

UPDATE ONETIMEDESIGNCOMPONENTS odc
SET PLANNEDSYSTEMTYPEID = (
	SELECT Max(st.SystemTypeId) from SystemTypes st INNER JOIN SystemTypesMajorHardwareBuilds stmhb on st.systemtypeid = stmhb.systemtypeid AND ISMAIN = 1
	AND st.MAJORSOFTWAREBUILDSID = odc.MAJORSOFTWAREBUILDSID AND stmhb.MAJORHARDWAREID = odc.MAJORHARDWAREBUILDSID
	WHERE st.MAJORSOFTWAREBUILDSID = odc.MAJORSOFTWAREBUILDSID AND stmhb.MAJORHARDWAREID = odc.MAJORHARDWAREBUILDSID
);
commit;

INSERT INTO DesignComponents (CREATIONUSER,MODIFICATIONUSER,DELETED,SYSTEMTYPEID,GDPRRELEVANT,SUBNETWORKBOUNDARYID,DESIGNCOMPONENTFAMILYID,MAJORSOFTWAREBUILDSID, VISIBLEFLAG)
Select Distinct 1,1,0,PLANNEDSYSTEMTYPEID,GDPRRELEVANT,SUBNETWORKBOUNDARYID,PlannedDESIGNCOMPONENTFAMILYID,MAJORSOFTWAREBUILDSID,VISIBLEFLAG FROM ONETIMEDESIGNCOMPONENTS;

commit;

UPDATE ONETIMEDESIGNCOMPONENTS odc
SET PLANNEDDESIGNCOMPONENTID = (
	SELECT dc.DesignComponentId from DesignComponents dc
	WHERE dc.systemtypeid = odc.systemtypeid 
	AND dc.SUBNETWORKBOUNDARYID = odc.SUBNETWORKBOUNDARYID
	AND platformId = (Select PlatformId from  Platforms WHERE Platform = 'CEE-CNIS')
	AND Deleted = 0
);
commit;
CREATE TABLE PlannedActivities_Backup_17122025
AS
Select * from PlannedActivities;

INSERT INTO PlannedActivities (CREATIONUSER,MODIFICATIONUSER,DELETED,PLANNEDIMPLEMENTATIONYEAR,ACTIVITYSTATUSID,PLANNINGACTIVITYSTATUSID,PLANNEDACTIVITYRESOURCEID,ENGINEERINGRISKID,OPERATIONALRISKID,
OPCOID,DESIGNASPECTID,DESIGNCOMPONENTFAMILYID,DELIVERYPLANAVAILABLE,PLANNEDACTIVITYCATEGORYID,ISNEWSERVICEARCHITECTURE,ISREPLACEMENTEXISTINGSOLUTION, BUILDBAGID,PLANNEDCOMPLETION,RESPONSIBILITYPHASEID,BUDGETAVAILABILITYID,DeliveryStatusId)
Select Distinct 1,1,0,2029,(select ACTIVITYSTATUSID from ActivityStatuses where ACTIVITYSTATUS = 'In Planning'),(select PLANNINGACTIVITYSTATUSID from planningactivitystatuses where UPPER(PLANNINGACTIVITYSTATUS) = 'PROPOSED'),
(select plannedactivityresourceid from plannedactivityresources where plannedactivityresource = 'Platform Migration'), 1,1,DA.OPCOID,DA.ID,ODC.PLANNEDDESIGNCOMPONENTFAMILYID,1, (Select PLANNEDACTIVITYCATEGORYID from plannedactivitycategory where CATEGORYDESCRIPTION = 'HW'),0,0,(select BUILDBAGID from buildbags where BAGDESCRIPTION = 'Empty'), TO_DATE('31-03-2028','DD-MM-YYYY'),1,1,(Select DeliveryStatusId from deliverystatuses WHERE DELIVERYSTATUS = 'Ready to start migration')  FROM DesignAspects DA JOIN ONETIMEDESIGNCOMPONENTS ODC ON DA.DESIGNCOMPONENTFAMILYID = ODC.DESIGNCOMPONENTFAMILYID WHERE DA.DELETED = 0;
commit;

CREATE TABLE ONETIMEPlannedActivities (OPCOID  NUMBER(5),DESIGNASPECTID NUMBER(19),PLANNEDACTIVITYID NUMBER(19));

INSERT INTO ONETIMEPlannedActivities (OPCOID,DESIGNASPECTID,PLANNEDACTIVITYID)
Select Distinct DA.OPCOID,DA.ID,PLANNEDACTIVITYID FROM PlannedActivities pa JOIN DesignAspects da ON pa.designaspectid = da.id
JOIN ONETIMEDESIGNCOMPONENTS ODC ON pa.DESIGNCOMPONENTFAMILYID = ODC.PLANNEDDESIGNCOMPONENTFAMILYID AND da.DESIGNCOMPONENTFAMILYID = ODC.DESIGNCOMPONENTFAMILYID;

commit;

INSERT INTO DAASSETMIGRATION (PLANNEDACTIVITYID,NETWORKELEMENTASPLANNEDID,TARGETDESIGNCOMPONENETID,ENVIRONMENTID,DEPLOYMENTSTATUSID,OPCOID,LOCATIONID,RFODATE,RFSDATE,MIGRATIONCOMPLETIONDATE,CREATIONUSER,
MODIFICATIONUSER,DELETED)
SELECT Distinct PA.PLANNEDACTIVITYID,asset.NETWORKELEMENTASPLANNEDID,ODC.PLANNEDDESIGNCOMPONENTID,asset.ENVIRONMENTID,asset.DEPLOYMENTSTATUSID,asset.OPCOID,asset.LOCATIONID,RFO_Date,RFS_Date,Migration_Date,1,1,0
FROM DesignAspects DA INNER JOIN OPCOS OP on OP.OPCOID = DA.OPCOID AND OP.DELETED = 0
INNER JOIN PlannedActivities PA ON DA.ID = PA.DesignAspectId AND DA.Deleted = 0 AND PA.Archived = 0 and PA.Deleted = 0
INNER JOIN NetworkElementsAsPlanned asset ON DA.OpCOID = Asset.OpCoId AND Asset.DESIGNCOMPONENTFAMILYID = DA.DESIGNCOMPONENTFAMILYID AND asset.deleted = 0
INNER JOIN ExodusPlanBackup Plan ON UPPER(OP.OPCO) = UPPER(plan.OPCO) AND asset.ElementName = Plan.ElementName
INNER JOIN ONETIMEDESIGNCOMPONENTS ODC ON ODC.DesignComponentId = Asset.DesignComponentId
WHERE asset.DEPLOYMENTSTATUSID IN (Select DEPLOYMENTSTATUSID FROM DEPLOYMENTSTATUSES WHERE DEPLOYMENTSTATUS IN ('IN-SERVICE','IN COMMISSIONING','PLANNED'));


commit;

